const express = require('express');
const { Pool } = require('pg');

const app = express();

// Postgres pool. Configuration is taken from the standard PG* / DATABASE_URL
// environment variables so it works the same in dev, CI, and k8s.
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Readiness probe for k8s. Returns 200 when we can reach Postgres,
// 503 otherwise. Kept intentionally lightweight: a single `SELECT 1`.
app.get('/healthz', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.status(200).json({ db: 'ok' });
  } catch (err) {
    res.status(503).json({ db: 'error' });
  }
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/* istanbul ignore next */
if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

