// Simple application for agent to work on

const express = require('express');
const app = express();

// Lazy-load pg so the module is optional in environments/tests that
// don't need a real DB. Tests can override the pool via app.locals.dbPool.
function getPool() {
  if (app.locals.dbPool) return app.locals.dbPool;
  try {
    const { Pool } = require('pg');
    app.locals.dbPool = new Pool({
      connectionString: process.env.DATABASE_URL,
      // Keep the readiness probe snappy.
      connectionTimeoutMillis: 2000,
    });
    return app.locals.dbPool;
  } catch (err) {
    return null;
  }
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Kubernetes readiness probe: 200 only when Postgres is reachable.
app.get('/healthz', async (req, res) => {
  const pool = getPool();
  if (!pool) {
    return res.status(503).json({ db: 'unavailable' });
  }
  try {
    await pool.query('SELECT 1');
    return res.status(200).json({ db: 'ok' });
  } catch (err) {
    return res.status(503).json({ db: 'error' });
  }
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
